metadata.orrery:spec:
# yaml-language-server: $schema=https://raw.githubusercontent.com/Sagargupta16/orrery/main/skills/orrery/references/diagram.schema.json # Chart kit composition, planned from the code on 2026-10-22 (branch feat/chart-motion). # Evidence paths are relative to the repo root; every edge is a real render (<X ... />) or call. # # leftOut (put back on request): # - Callers of the Standard* wrappers (MonthlyFlowChart, CohortSpendingAnalysis, the FIRE calculator panels, # DayOfWeekChart, FinancialHealthScore, CFPScoreView and other pages): one hop further out; MonthlyFlowChart # renders StandardBarChart (components/analytics/MonthlyFlowChart.tsx:81). # - CashFlowForecast panel: it only renders CashFlowForecastChart (components/analytics/CashFlowForecast.tsx:71). # - SafeToSpendCard renders BalanceProjectionChart (components/analytics/SafeToSpendCard.tsx:135) and the FIRE # Monte Carlo results render MonteCarloFanChart (pages/fire-calculator/components/MonteCarloResults.tsx:67): # one hop further out, like the other callers. # - Sankey internals SankeyMarks, SankeyReadout, sankeyModel, sankeyLayout: folded into the SankeyDiagram node # (components/charts/SankeyDiagram.tsx:93-161). # - Treemap internals TreemapMarks, treemapLayout, treemapModel: folded into the Treemap node # (components/charts/Treemap.tsx:190). # - ExpenseTreemap renders CategoryTreemap (components/analytics/ExpenseTreemap.tsx:21) and ComparisonPage renders # CategorySlopeChart (pages/comparison/ComparisonPage.tsx:216): named in notes, one hop further out. # - Grid's TickLayer, used by Axis (components/charts/Axis.tsx:15): folded into the CartesianChart children node. # - Shared helpers scales.ts, paths.ts, chartContext.ts, useElementSize.ts, usePrinting.ts: imported by most kit # files, so no node and no arrows (loop.md rung 1); named in the CartesianChart and ChartFrame notes # (components/charts/CartesianChart.tsx:130, components/charts/ChartFrame.tsx:59-62). # - Per-file animation use: every mark calls chartTransition or CHART_MOTION and draws motion elements # (Bars.tsx:79-88, PieChart.tsx:174-188, SankeyDiagram.tsx:27, ChartBrush.tsx:198, TreemapMarks.tsx:110, # SlopeChart.tsx:121-136) and ChartFrame calls useInView (ChartFrame.tsx:61); drawn as one kit -> Motion 14 arrow. The chartMotion tokens # (components/charts/chartMotion.ts:9) are folded into the Motion 14 node note. # - Folded nodes: StandardBarChart (used by MonthlyFlowChart), StandardAreaChart and TimeSeriesLineChart are one # "Standard x/y wrappers" node (StandardBarChart.tsx:110, StandardAreaChart.tsx:84, TimeSeriesLineChart.tsx:41); # Bars, LineSeries, AreaSeries, Axis, Grid, References, CartesianTooltip and Crosshair are one # "CartesianChart children" node (Bars.tsx:71, LineSeries.tsx:46, AreaSeries.tsx:25, Axis.tsx:68, Grid.tsx:33, # References.tsx:63, CartesianTooltip.tsx:65, Crosshair.tsx:24). # - Custom children and overlays written by consumers: PieCenterReadout, ValueSortedTooltip, NetWorthTooltip, # ProjectionReveal (they read chartContext like the kit's own children). # - Sparkline, ProgressBar, CircularProgress: reuse chartMotion and usePrinting without ChartFrame, so they are # not part of the kit's composition (components/shared/Sparkline.tsx:5, components/shared/ProgressBar.tsx:4). # - useChartRange (components/ui) behind ChartBrush, and the stores ChartFrame reads (motionStore, themeStore, # useIsMobile): app state, not chart parts. # - Tests under __tests__. # standIns: Motion 14 drawn with tabler:brand-framer-motion (Motion is the renamed Framer Motion; its own # logo is not in the icon catalog). title: "Chart kit: components/charts and who renders it" subtitle: In-house animated SVG charts that replaced Recharts; every chart root draws inside ChartFrame and animates with Motion 14 direction: right layout: { spacing: 0.5 }
groups: wrappers: type: zone label: Analytics wrappers (components/analytics) evidence: frontend/src/components/analytics pages: type: zone label: Page charts (pages/*) evidence: frontend/src/pages kit: type: zone label: Chart kit (components/charts) evidence: frontend/src/components/charts
nodes: # Wrappers in components/analytics, in the order their arrows enter the kit. cat-treemap: icon: tabler:chart-treemap label: CategoryTreemap note: used by ExpenseTreemap in: wrappers evidence: - "frontend/src/components/analytics/CategoryTreemap.tsx:43#CategoryTreemap" - "frontend/src/components/analytics/ExpenseTreemap.tsx:21#CategoryTreemap" std-radar: icon: tabler:chart-radar label: StandardRadarChart note: health score in: wrappers evidence: "frontend/src/components/analytics/StandardRadarChart.tsx:35#StandardRadarChart" bespoke: icon: tabler:chart-histogram label: Bespoke analytics charts badge: x4 note: Pareto, effective tax rate, cash flow forecast, balance projection in: wrappers evidence: - "frontend/src/components/analytics/ParetoChart.tsx:81#ParetoChart" - "frontend/src/components/analytics/EffectiveTaxRateChart.tsx:54#EffectiveTaxRateChart" - "frontend/src/components/analytics/CashFlowForecastChart.tsx:86#CashFlowForecastChart" - "frontend/src/components/analytics/BalanceProjectionChart.tsx:54#BalanceProjectionChart" std-xy: icon: tabler:chart-line label: Standard x/y wrappers badge: x3 note: bar, area, time-series line in: wrappers evidence: - "frontend/src/components/analytics/StandardBarChart.tsx:111#StandardBarChart" - "frontend/src/components/analytics/StandardAreaChart.tsx:89#StandardAreaChart" - "frontend/src/components/analytics/TimeSeriesLineChart.tsx:44#TimeSeriesLineChart" std-pie: icon: tabler:chart-pie label: StandardPieChart in: wrappers evidence: "frontend/src/components/analytics/StandardPieChart.tsx:70#StandardPieChart"
