page-slope: icon: tabler:app-window label: Comparison page note: CategorySlopeChart in: pages evidence: - "frontend/src/pages/comparison/components/CategorySlopeChart.tsx:51#SlopeChart" - "frontend/src/pages/comparison/ComparisonPage.tsx:216#CategorySlopeChart"
# The kit: chart roots, in the order the wrappers and pages above enter them, then ChartFrame. # CartesianChart children share the roots' column (align) right under CartesianChart, so their # one arrow stays out of the arrows into ChartFrame. treemap: icon: tabler:chart-treemap label: Treemap note: zoomable tiles in: kit evidence: - "frontend/src/components/charts/Treemap.tsx:39#Treemap" - "frontend/src/components/charts/Treemap.tsx:187#ChartFrame" radar: icon: tabler:radar-2 label: RadarChart in: kit evidence: "frontend/src/components/charts/RadarChart.tsx:60#RadarChart" cartesian: icon: tabler:chart-dots label: CartesianChart note: scales, context, active row, pointer in: kit evidence: "frontend/src/components/charts/CartesianChart.tsx:62#CartesianChart" children: icon: tabler:chart-area-line label: CartesianChart children note: marks, axes, references, tooltip in: kit align: cartesian evidence: - "frontend/src/components/charts/CartesianChart.tsx:137#CartesianContext" - "frontend/src/components/charts/Bars.tsx:71#Bars" - "frontend/src/components/charts/LineSeries.tsx:48#LineSeries" - "frontend/src/components/charts/AreaSeries.tsx:27#AreaSeries" - "frontend/src/components/charts/Axis.tsx:68#CategoryAxis" - "frontend/src/components/charts/Axis.tsx:100#ValueAxis" - "frontend/src/components/charts/Grid.tsx:33#Grid" - "frontend/src/components/charts/References.tsx:63#ReferenceLine" - "frontend/src/components/charts/References.tsx:113#ReferenceArea" - "frontend/src/components/charts/References.tsx:143#ReferenceDot" - "frontend/src/components/charts/CartesianTooltip.tsx:65#CartesianTooltip" - "frontend/src/components/charts/Crosshair.tsx:24#Crosshair" brush: icon: tabler:adjustments-horizontal label: ChartBrush note: zoom range in: kit evidence: "frontend/src/components/charts/ChartBrush.tsx:59#ChartBrush" pie: icon: tabler:chart-pie-2 label: PieChart in: kit evidence: "frontend/src/components/charts/PieChart.tsx:61#PieChart" sankey: icon: tabler:chart-sankey label: SankeyDiagram note: marks, readout, layout model in: kit evidence: "frontend/src/components/charts/SankeyDiagram.tsx:57#SankeyDiagram" slope: icon: tabler:trending-up label: SlopeChart in: kit evidence: - "frontend/src/components/charts/SlopeChart.tsx:57#SlopeChart" - "frontend/src/components/charts/SlopeChart.tsx:81#ChartFrame" frame: icon: tabler:frame label: ChartFrame note: size, in-view entrance, print, a11y in: kit evidence: "frontend/src/components/charts/ChartFrame.tsx:43#ChartFrame"
